import { labs, simulate } from './models.mjs';
import { referencesByLab, maturityLevels, projectMaturity, referenceNotice } from './references.mjs';

const BASE='/education/research-labs/';
const FIELD=BASE+'post-disaster-reconstruction/';
const A=BASE+'assets/';
const $=(s,r=document)=>r.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=new Intl.NumberFormat('en-US',{maximumFractionDigits:1});
const num=v=>typeof v==='number'?nf.format(v):esc(v);
const icons={arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',back:'<path d="M20 12H5m6-6-6 6 6 6"/>',up:'<path d="M5 19 19 5M5 5h14v14"/>',play:'<path d="m9 5 11 7-11 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',reset:'<path d="M4 10a8 8 0 1 1 1 8M4 4v6h6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',chevron:'<path d="m6 9 6 6 6-6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',save:'<path d="M5 3h12l4 4v14H3V3h2m2 0v6h10V3M7 21v-8h10v8"/>',compare:'<path d="M9 3v18m6-18v18M3 8h5M3 16h5m8-8h5m-5 8h5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',book:'<path d="M12 5C8 2 3 4 3 4v15s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1zm0 0v15"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.arrow}</svg>`;
const brand=()=>`<a class="brand brand-logo" href="${BASE}" aria-label="Barchinet Global Research Labs home"><img src="${A}barchinet-global.svg" alt="Barchinet Global" width="900" height="230"><small>RESEARCH LABS / EDUCATION</small></a>`;
const art={circularbuild:'circular',panelbuild:'panel',vernacular:'vernacular',reliefroute:'relief',shelterspace:'shelter'};
const names={circularbuild:'CircularBuild',panelbuild:'PanelBuild',vernacular:'Vernacular Futures',reliefroute:'ReliefRoute',shelterspace:'ShelterSpace'};
const cardCopy={circularbuild:'Turn demolition materials into a resource plan. Explore what to recover, where it goes, and what it costs.',panelbuild:'Balance the speed, cost and material impact of prefabricated recovery housing.',vernacular:'Explore how local materials shape the long-term cost and impact of rebuilding.',reliefroute:'Get essential supplies to the right places when roads, time and capacity are limited.',shelterspace:'Explore temporary shelter capacity in sports venues. See who is assigned a place, and who is left out.'};
const categories={circularbuild:'Circular materials · Urban recovery',panelbuild:'Rapid construction · Housing',vernacular:'Local materials · Life cycle',reliefroute:'Humanitarian logistics · Routing',shelterspace:'Emergency shelter · Allocation'};
const appMission={circularbuild:'Recover more. Understand the trade-offs.',panelbuild:'Build sooner. See the full picture.',vernacular:'Rebuild locally. Think in decades.',reliefroute:'Every route is a recovery decision.',shelterspace:'Space is limited. Access matters.'};
let id=location.pathname.split('/').filter(Boolean).find(v=>labs.some(l=>l.id===v));
let lab=id?labs.find(l=>l.id===id):null;
let state=lab?{...lab.defaults}:{};
let result, role=0, view='model', saved=null, guideOpen=false, guideStep=0, guidePlaying=false, guideTimer, toastTimer;
let motion=!matchMedia('(prefers-reduced-motion: reduce)').matches;
let media={};
const app=$('#app');

function maturityBadge(labId,interactive=false){const m=projectMaturity[labId];if(!m)return '';const inner=`<span class="maturity-dot" aria-hidden="true"></span><span>${esc(m.label)}</span><span class="maturity-level">${m.currentLevel} / ${maturityLevels.length}</span>${interactive?'<span class="maturity-open">Maturity ↗</span>':''}`;return interactive?`<button class="maturity-badge" id="maturity" type="button" aria-label="Research maturity: ${esc(m.label)}, level ${m.currentLevel} of ${maturityLevels.length}. View criteria">${inner}</button>`:`<span class="maturity-badge card-maturity">${inner}</span>`}
function bibliographyHtml(){const refs=referencesByLab[id]||[];if(!refs.length)return '';const groups=[{title:'Research articles',items:refs.filter(r=>r.type==='Peer-reviewed research article')},{title:'Standards, handbooks & method references',items:refs.filter(r=>r.type!=='Peer-reviewed research article')}];return `<details class="academic-sources"><summary><span>Academic sources & method references</span><span class="reference-count">${refs.length} sources ${icon('chevron')}</span></summary><p class="reference-notice">${esc(referenceNotice)}</p>${groups.filter(g=>g.items.length).map(g=>`<section class="reference-group"><h3>${g.title}</h3>${g.items.map(r=>`<article class="reference-entry"><div class="reference-type">${esc(r.type)} · ${esc(r.year)}</div><h4><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ${icon('up')}</a></h4><p class="reference-citation">${r.authors.map(esc).join('; ')} (${esc(r.year)}). ${esc(r.publisher)}.</p>${r.doi?`<a class="reference-doi" href="https://doi.org/${esc(r.doi)}" target="_blank" rel="noopener noreferrer">DOI: ${esc(r.doi)}</a>`:''}<dl><div><dt>What this informs</dt><dd>${esc(r.usedFor)}</dd></div><div><dt>Scope & limitation</dt><dd>${esc(r.limitation)}</dd></div></dl></article>`).join('')}</section>`).join('')}</details>`}
function showMaturity(){const m=projectMaturity[id];openModal('Research maturity',`<div class="maturity-current">${maturityBadge(id)}<p>${esc(m.description)}</p></div><div class="maturity-evidence"><strong>Project-specific evidence register</strong><p>${m.verifiedEvidence.length?m.verifiedEvidence.map(esc).join(' · '):'No project-specific evidence has been recorded in this demo.'}</p></div><p class="maturity-caption">A Barchinet learning framework for the underlying research product. Required evidence below is a criterion, not a completed milestone or an external certification.</p><ol class="maturity-ladder">${maturityLevels.map(l=>`<li class="${l.level===m.currentLevel?'current':''}"><span class="ladder-number">${String(l.level).padStart(2,'0')}</span><div><h3>${esc(l.title)} ${l.level===m.currentLevel?'<span>Current recorded level</span>':''}</h3><ul>${l.evidenceRequired.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div></li>`).join('')}</ol>`)}

function footer(){return `<footer class="footer"><span>© ${new Date().getFullYear()} <a href="/">Barchinet Global</a> · Research Labs</span><span>Built for learning. Made to be explored.</span><a href="${BASE}#about">About the training models ${icon('up')}</a><a href="/website-privacy.html">Website privacy</a></footer>`}
function renderHub(){
 document.title='Research Labs — Barchinet Global Education';
 app.innerHTML=`<div class="container"><header class="site-head">${brand()}<nav class="nav" aria-label="Research Labs navigation"><a href="#fields">Research fields</a><a href="#approach">The approach</a><span class="edu">${icon('book')} Research Labs</span></nav></header><main id="main"><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> Education / Research Labs</div><h1>Research,<br>made <em>useful.</em></h1><p>A place to see what research can become.<br>Explore working applications organised by research field — and follow an idea from evidence to everyday use.</p><a class="button primary" href="#fields">Explore research fields ${icon('arrow')}</a><div class="hero-meta">${icon('check')} Learn the method. Experience the product.</div></div><a class="hero-art" href="${FIELD}" aria-label="Explore the Post-disaster reconstruction collection"><img src="${A}relief.png" alt="Architectural model of a fictional city, river, bridges and recovery hubs" fetchpriority="high"><span class="art-label"><span class="dot"></span> RESEARCH → MODEL → PRODUCT</span><div class="art-caption"><div><strong>Post-disaster reconstruction</strong><span>Our first collection · Five independent web apps</span></div><span class="round-arrow">${icon('arrow')}</span></div></a></section><section id="fields"><div class="section-head"><div><div class="eyebrow" style="margin-bottom:11px">01 — Explore a research field</div><h2>Different questions. Useful tools.</h2></div><p>Each field has its own collection.<br>Every application starts with a decision someone needs to make.</p></div><a class="field-card" href="${FIELD}"><div class="field-image"><img src="${A}shelter.png" alt="Architectural model of a sports arena repurposed for temporary accommodation" loading="lazy"><span class="cover-num">01</span></div><div class="field-copy"><div class="eyebrow">Post-disaster studies <span class="field-count">5 WEB APPS</span></div><h3>Post-disaster<br>reconstruction</h3><p>Explore material recovery, rapid housing, whole-life design, relief routes and temporary shelter. Five ways to turn reconstruction research into practical decisions for different users.</p><span class="field-enter">Explore the collection ${icon('arrow')}</span></div></a><a class="field-card" style="margin-top:24px" href="${BASE}architecture/"><div class="field-image"><img src="${A}architecture/sketch-01.png" alt="AI-generated architectural courtyard sketch with conceptual notes" loading="lazy"><span class="cover-num">02</span></div><div class="field-copy"><div class="eyebrow">Architecture & design studies <span class="field-count">3 WEB APPS</span></div><h3>Architecture</h3><p>Read the thinking behind a sketch. Explore design annotations, read a curated project record and compare prepared studio perspectives.</p><span class="field-enter">Explore the collection ${icon('arrow')}</span></div></a><a class="field-card" href="/education/research-labs/rural-architecture/"><div class="field-image"><img src="/education/research-labs/assets/rural-architecture/cheshmeh-sar.png" alt="Synthetic architectural study of a fictional mountain village" loading="lazy"><span class="cover-num">03</span></div><div class="field-copy"><div class="eyebrow">Vernacular architecture <span class="field-count">3 WEB APPS</span></div><h3>Rural architecture</h3><p>Explore three fictional villages, compare architectural elements and trace design prompts to their source observations.</p><span class="field-enter">Explore the collection →</span></div></a></section><section id="approach" class="journey"><div class="eyebrow">02 — From a paper to a purpose</div><h2>A global product begins with<br>a useful decision.</h2><div class="journey-track"><div><span>01 / RESEARCH</span><h3>Ask a better question.</h3><p>Define the problem, the evidence and the limits of what you know.</p></div><div><span>02 / MODEL</span><h3>Make it testable.</h3><p>Turn relationships into inputs, constraints and transparent calculations.</p></div><div><span>03 / PRODUCT</span><h3>Design for someone.</h3><p>Give different users a clear task, useful feedback and an understandable result.</p></div><div><span>04 / GLOBAL USE</span><h3>Make it adaptable.</h3><p>Validate locally. Adapt languages, units, data, access and workflows.</p></div></div></section><section id="about" class="footnote"><div><div class="eyebrow" style="margin-bottom:13px">03 — A place for research to grow</div><h2>One platform.<br>Distinct research collections.</h2></div><p>Research Labs is the shared home for field-specific collections and independent applications. Current collections explore post-disaster reconstruction, architecture and rural architecture. These learning prototypes use synthetic data, transparent calculations and method references; developing a global product also requires user research, local evidence, validation and continuing maintenance.</p></section></main>${footer()}</div>`;
}
function renderCollection(){
 document.title='Post-disaster Reconstruction — Barchinet Global Research Labs';
 app.innerHTML=`<div class="container"><header class="site-head">${brand()}<nav class="nav" aria-label="Main navigation"><a href="#labs">The labs</a><a href="#approach">The approach</a><a class="edu" href="${BASE}">${icon('back')} Research Labs</a></nav></header><main id="main"><section class="hero collection-hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> Education / Research Labs / Collection 01</div><h1>Post-disaster<br><em>reconstruction.</em></h1><p>Five independent web apps exploring how research can support recovery — from material reuse to housing, relief logistics and emergency shelter.</p><a class="button primary" href="#labs">Find your first lab ${icon('arrow')}</a><div class="hero-meta">${icon('check')} No setup. No specialist software. Just curiosity.</div></div><a class="hero-art" href="${FIELD}reliefroute/" aria-label="Explore ReliefRoute Lab"><img src="${A}relief.png" alt="Architectural model of a fictional city, river, bridges and relief distribution hubs" fetchpriority="high"><span class="art-label"><span class="dot"></span> THE RESEARCH → PRODUCT COLLECTION</span><div class="art-caption"><div><strong>A road closes. What changes?</strong><span>Explore the decision inside ReliefRoute Lab.</span></div><span class="round-arrow">${icon('arrow')}</span></div></a></section><section id="labs"><div class="section-head"><div><div class="eyebrow" style="margin-bottom:11px">01 — Choose a question</div><h2>Your next idea starts here.</h2></div><p>Each lab is a separate working web app.<br>Pick a role. Change an assumption. See why it matters.</p></div><div class="lab-grid">${labs.map((l,i)=>`<a class="lab-card" href="${FIELD}${l.id}/"><div class="cover"><img src="${A}${art[l.id]}.png" alt="Concept model for ${esc(names[l.id])}" loading="lazy"><span class="cover-num">0${i+1}</span></div><div class="card-title"><h3>${esc(names[l.id])}</h3>${icon('up')}</div><p>${esc(cardCopy[l.id])}</p>${maturityBadge(l.id)}<div class="card-tag">${esc(categories[l.id])}</div></a>`).join('')}</div></section><section id="approach" class="journey"><div class="eyebrow">02 — From a paper to a purpose</div><h2>A global product begins with<br>a useful decision.</h2><div class="journey-track"><div><span>01 / RESEARCH</span><h3>Ask a better question.</h3><p>Define the problem, the evidence and the limits of what you know.</p></div><div><span>02 / MODEL</span><h3>Make it testable.</h3><p>Turn relationships into inputs, constraints and transparent calculations.</p></div><div><span>03 / PRODUCT</span><h3>Design for someone.</h3><p>Give different users a clear task, useful feedback and an understandable result.</p></div><div><span>04 / GLOBAL USE</span><h3>Make it adaptable.</h3><p>Validate locally. Adapt languages, units, data, access and workflows.</p></div></div></section><section id="about" class="footnote"><div><div class="eyebrow" style="margin-bottom:13px">03 — Learn with the model</div><h2>Fictional places.<br>Transparent reasoning.</h2></div><p>These educational prototypes use synthetic training data and simplified, inspectable calculations. Their references explain the underlying methods; they do not certify these apps or their results. Explore assumptions and worked examples inside every lab. Turning a prototype into a market-ready product requires user research, local evidence, validation and ongoing maintenance.</p></section></main>${footer()}</div>`;
}
function controlHtml(c,i){const v=state[c.key]??c.value;return `<div class="control" data-control="${esc(c.key)}"><label class="control-label" for="c-${esc(c.key)}"><span>${esc(c.label)}</span>${c.type!=='select'?`<output for="c-${esc(c.key)}" id="o-${esc(c.key)}">${num(v)} ${esc(c.unit||'')}</output>`:''}</label>${c.type==='select'?`<select id="c-${esc(c.key)}" data-key="${esc(c.key)}">${c.options.map(o=>`<option value="${esc(typeof o==='object'?o.value:o)}" ${String(v)===String(typeof o==='object'?o.value:o)?'selected':''}>${esc(id==='shelterspace'&&c.key==='access'?(o.value==='balanced'?'Farther first':'District order'):(typeof o==='object'?o.label:o))}</option>`).join('')}</select>`:`<input type="range" id="c-${esc(c.key)}" data-key="${esc(c.key)}" min="${c.min}" max="${c.max}" step="${c.step||1}" value="${v}"><div class="range-ends"><span>${num(c.min)}</span><span>${num(c.max)} ${esc(c.unit||'')}</span></div>`}</div>`}
function renderLab(){
 document.title=`${names[id]} Lab — Barchinet Global`;
 document.body.className='lab-page';
 app.innerHTML=`<div class="lab-shell"><header class="app-head">${brand()}<a class="back-link" href="${FIELD}">${icon('back')} Post-disaster reconstruction</a><span class="training-pill"><span class="dot"></span> Synthetic training data</span></header><main id="main"><div class="app-heading"><div><div class="eyebrow"><span class="dot"></span> ${esc(categories[id])}</div><h1>${esc(names[id])} <span style="font-weight:400;color:var(--muted)">Lab</span></h1><p>${esc(lab.mission)}</p><div class="app-maturity">${maturityBadge(id,true)}</div></div><div class="heading-actions"><button class="button light" id="product-lens">${icon('up')} The product lens</button><a class="button light" href="#field-notes">${icon('book')} Field notes</a></div></div><section class="worked-example-panel" id="worked-example-panel" aria-label="Worked example"></section><div class="workspace"><aside class="scenario-panel" aria-label="Scenario controls"><div class="role-section"><div class="panel-label">Explore as</div><select class="role-select" id="role" aria-label="Choose your role">${lab.roles.map((r,i)=>`<option value="${i}" title="${esc(r.name)}" aria-label="${esc(r.name)}">${esc(id==='shelterspace'&&r.name==='Accessibility planner'?'Access planner':id==='shelterspace'&&r.name==='Shelter coordinator'?'Shelter lead':r.name)}</option>`).join('')}</select><p class="role-goal" id="role-goal">${esc(lab.roles[role].goal)}</p></div><div class="panel-label">Your scenario</div><h2 class="scenario-name">What would you change?</h2>${lab.controls.map(controlHtml).join('')}<div class="scenario-bottom"><button class="text-button" id="reset">${icon('reset')} Reset scenario</button><p class="demo-note">Illustrative inputs · All costs in demo USD. Change one input to follow its effect.</p></div></aside><section class="model-panel" aria-label="Interactive results"><div class="model-toolbar"><div class="view-tabs" role="tablist" aria-label="Model view"><button class="view-tab active" id="view-model" role="tab" aria-controls="stage" aria-selected="true" tabindex="0" data-view="model">Live model</button><button class="view-tab" id="view-scene" role="tab" aria-controls="stage" aria-selected="false" tabindex="-1" data-view="scene">Concept scene</button><button class="view-tab" role="tab" aria-controls="stage" aria-selected="false" tabindex="-1" data-view="video" id="video-tab" hidden>Motion story</button></div><label class="motion-toggle"><input type="checkbox" id="motion" ${motion?'checked':''}> Motion</label></div><div class="model-stage ${motion?'':'motion-paused'}" id="stage" role="tabpanel" aria-labelledby="view-model" aria-label="Live model"></div><div class="metrics" id="metrics" aria-label="Scenario results"></div><div id="result-status" class="sr-only" role="status" aria-live="polite"></div><div class="insight">${icon('spark')}<div id="insight"></div></div></section></div><div class="workspace-actions"><button class="button light" id="save">${icon('save')} Capture scenario A</button><button class="button light" id="compare" disabled>${icon('compare')} Compare A / B</button><button class="button light" id="export">${icon('download')} Export scenario</button></div><section class="guide-section" aria-labelledby="guide-title"><div class="guide-top"><div><h2 id="guide-title">Follow the research.</h2><p>A four-step, worked walkthrough of your current scenario.</p></div><button class="button" id="guide-toggle">${icon('play')} Start guide</button></div><div id="guide-body" hidden></div></section><details class="notes" id="field-notes"><summary>Field notes · calculations, assumptions & references ${icon('chevron')}</summary><div class="notes-grid"><div><h3>How this model works</h3><ul>${(Array.isArray(lab.methods)?lab.methods:[lab.methods]).filter(Boolean).map(m=>`<li>${esc(m)}</li>`).join('')}</ul></div><div><h3>What we assume</h3><ul>${(Array.isArray(lab.assumptions)?lab.assumptions:[lab.assumptions]).filter(Boolean).map(m=>`<li>${esc(m)}</li>`).join('')}</ul></div><div><h3>Read the underlying methods</h3>${lab.sources.map(s=>`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ${icon('up')}</a>`).join('')}<p class="source-note">References inform the learning approach. Training coefficients are illustrative unless explicitly stated otherwise. Concept images and films are AI-generated illustrations, not measured outputs. This is an educational prototype, not a validated operational planning service.</p></div></div>${bibliographyHtml()}</details></main>${footer()}</div><dialog class="modal" id="modal" aria-labelledby="modal-title"></dialog><div role="status" aria-live="polite" id="toast" class="toast" hidden></div>`;
 bindLab();update();loadMedia();
}
function bindLab(){
 for(const c of lab.controls){const el=$(`#c-${c.key}`);el.addEventListener(c.type==='select'?'change':'input',()=>{pauseGuide();markWorkedCustomized();state[c.key]=c.type==='select'?el.value:Number(el.value);const out=$(`#o-${c.key}`);if(out)out.textContent=`${num(state[c.key])} ${c.unit||''}`;update()})}
 $('#role').onchange=e=>{pauseGuide();role=Number(e.target.value);$('#role-goal').textContent=lab.roles[role].goal;update();toast(`Exploring as ${lab.roles[role].name}. The highlighted result follows this role’s question.`)};
 for(const tab of document.querySelectorAll('[data-view]'))tab.onclick=()=>{pauseGuide();selectRecoveryView(tab.dataset.view);if(guideOpen)renderGuide()};
 $('.view-tabs').addEventListener('keydown',e=>{const tabs=[...document.querySelectorAll('[data-view]')].filter(t=>!t.hidden);const at=tabs.indexOf(document.activeElement);let next;if(e.key==='ArrowRight')next=(at+1)%tabs.length;else if(e.key==='ArrowLeft')next=(at+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();tabs[next].focus();tabs[next].click()});
 $('#motion').onchange=e=>{motion=e.target.checked;$('#stage').classList.toggle('motion-paused',!allowsRecoveryMotion());if(!allowsRecoveryMotion()){pauseGuide();const video=$('#stage video');if(video)video.pause();if(guideOpen)renderGuide()}};
 $('#reset').onclick=()=>{pauseGuide();markWorkedCustomized();guideStep=0;state={...lab.defaults};for(const c of lab.controls){$(`#c-${c.key}`).value=state[c.key];const out=$(`#o-${c.key}`);if(out)out.textContent=`${num(state[c.key])} ${c.unit||''}`}update();toast('Scenario reset. Your saved comparison stays available.')};
 $('#save').onclick=()=>{markWorkedCustomized();saved={inputs:{...state},result:structuredClone(result)};$('#compare').disabled=false;$('#save').innerHTML=icon('check')+' Scenario A captured';toast('Scenario A captured for this visit. Change inputs, then compare with B.')};
 $('#compare').onclick=showCompare;
 $('#export').onclick=()=>{const payload={app:names[id]+' Lab',purpose:'Educational prototype; synthetic training data',exportedAt:new Date().toISOString(),role:lab.roles[role].name,inputs:state,result,scenarioA:saved,references:referencesByLab[id]||lab.sources,methods:lab.methods,modelNotice:result.dataNotice,assumptions:lab.assumptions};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`barchinet-${id}-scenario.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Scenario and assumptions exported.')};
 $('#guide-toggle').onclick=()=>{guideOpen=!guideOpen;pauseGuide();if(guideOpen)selectRecoveryView('model');renderGuide();if(guideOpen)$('#guide-body').scrollIntoView({behavior:motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches?'smooth':'auto',block:'nearest'})};
 $('#product-lens').onclick=showProduct;
 $('#maturity').onclick=showMaturity;
 window.addEventListener('resize',updatePanHint);
 document.addEventListener('visibilitychange',()=>{if(document.hidden){pauseGuide();$('#stage video')?.pause();if(guideOpen)renderGuide()}});
 $('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
}
function update(){result=simulate(id,state);const focus={circularbuild:[1,0,2],panelbuild:[0,0,1],vernacular:[0,1,0],reliefroute:[0,2,1],shelterspace:[0,1,3]}[id]?.[role]??0;$('#metrics').innerHTML=result.metrics.map((m,i)=>`<div class="metric ${i===focus?'role-focus':''}" ${i===focus?'aria-label="Highlighted for your selected role"':''}><div class="metric-label">${esc(m.label)}${i===focus?'<span class="metric-focus-dot" title="Focus for your selected role"></span>':''}</div><div class="metric-value">${num(m.value)} <small>${esc(m.unit||'')}</small></div><span class="metric-detail">${esc(m.detail||'')}</span></div>`).join('');$('#insight').textContent=result.explanation;updateStage();announceRecoveryResults();renderWorkedExample();if(guideOpen)renderGuide()}
async function loadMedia(){try{const res=await fetch(A+'media.json');if(res.ok){media=await res.json();const entry=media[id]||media.videos?.[id];if(entry){const source=typeof entry==='string'?entry:entry.src||entry.url;if(source){$('#video-tab').hidden=false;media[id]=source.startsWith('/')||/^https?:/.test(source)?source:A+source}}}}catch{} }
function updatePanHint(){const drawing=$('.model-drawing');const hint=$('.model-swipe-hint');if(hint)hint.hidden=!(drawing&&drawing.scrollWidth>drawing.clientWidth+2)}
const svg=(label,body)=>`<svg viewBox="0 0 800 350" role="img" aria-label="${esc(label)}"><defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#dfe3d5" stroke-width=".5"/></pattern><marker id="arr" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="m0 0 10 5L0 10z" fill="#648273"/></marker></defs><rect width="800" height="350" fill="url(#grid)" opacity=".55"/>${body}</svg>`;
function drawModel(d){if(id==='circularbuild')return drawWaste(d);if(id==='panelbuild')return drawPanel(d);if(id==='vernacular')return drawVernacular(d);if(id==='reliefroute')return drawRelief(d);return drawShelter(d)}
function drawWaste(d){const mats=d.materials||[];const reuse=mats.reduce((s,m)=>s+m.reuse,0),recycle=mats.reduce((s,m)=>s+m.recycle,0);const outputs=[{label:'Reuse',mass:reuse,color:'#477c6c'},{label:'Recycle',mass:recycle,color:'#c49a4f'},{label:'Landfill',mass:d.landfill,color:'#bd795d'}];let body=`<text x="42" y="36" class="svg-title">MATERIALS LEAVING THE BUILDING</text><text x="560" y="36" class="svg-title">WHERE THEY GO</text>`;mats.forEach((m,i)=>{const y=70+i*51;body+=`<rect x="42" y="${y}" width="155" height="35" rx="7" fill="${m.color||'#c1c6b0'}" opacity=".35"/><rect x="42" y="${y}" width="4" height="35" rx="2" fill="${m.color||'#718c72'}"/><text x="54" y="${y+14}" class="svg-label">${esc(m.name)}</text><text x="54" y="${y+28}" class="svg-small">${num(m.mass)} t available</text>`;outputs.forEach((o,j)=>{const amount=[m.reuse,m.recycle,m.landfill][j];if(amount>.01)body+=`<path d="M197 ${y+17}C340 ${y+17} 385 ${86+j*82} 552 ${86+j*82}" fill="none" stroke="${o.color}" stroke-width="${Math.max(.4,amount/Math.max(1,d.total)*28)}" opacity=".25"/><path d="M197 ${y+17}C340 ${y+17} 385 ${86+j*82} 552 ${86+j*82}" fill="none" stroke="${o.color}" stroke-width="1.3" opacity=".6" class="flow-line"/>`})});outputs.forEach((o,j)=>body+=`<rect x="552" y="${64+j*82}" width="193" height="56" rx="9" fill="#fffdf4" stroke="#d6dccb"/><circle cx="570" cy="${84+j*82}" r="4" fill="${o.color}"/><text x="583" y="${88+j*82}" class="svg-title">${o.label}</text><text x="570" y="${108+j*82}" class="svg-value">${num(o.mass)} <tspan class="svg-small">tonnes</tspan></text>`);body+=`<text x="42" y="338" class="svg-label">${num(d.total)} t total material</text><text x="552" y="338" class="svg-label">${num(d.total?d.recovered/d.total*100:0)}% diverted from landfill</text>`;return svg('Material flows from demolition to reuse, recycling and landfill. Flow widths indicate material shares within this scenario; exact quantities are listed in the calculated breakdown.',body)}
function mapped(points){const xs=points.map(p=>p.x),ys=points.map(p=>p.y);const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);return new Map(points.map(p=>[p.id,{...p,px:75+(p.x-minX)/Math.max(1,maxX-minX)*650,py:65+(p.y-minY)/Math.max(1,maxY-minY)*205}]))}
function drawRelief(d){const nodes=d.nodes||[],map=mapped(nodes);let body=`<text x="35" y="30" class="svg-title">A FICTIONAL DISTRIBUTION NETWORK</text><path d="M365 45Q415 100 365 160T390 305" stroke="#b7d4ce" stroke-width="20" fill="none" opacity=".6"/>`;(d.edges||[]).forEach(e=>{const a=map.get(e.a),b=map.get(e.b);if(!a||!b)return;body+=`<path d="M${a.px} ${a.py}L${b.px} ${b.py}" class="svg-road" ${e.closed?'style="stroke:#c98468;stroke-dasharray:6 7"':''}/>`;if(e.closed)body+=`<circle cx="${(a.px+b.px)/2}" cy="${(a.py+b.py)/2}" r="10" fill="#b36349"/><path d="m${(a.px+b.px)/2-4} ${(a.py+b.py)/2-4} 8 8m-8 0 8-8" stroke="white" stroke-width="1.5"/>`});(d.routes||[]).forEach((r,i)=>{const pts=(r.path||[]).map(n=>map.get(n)).filter(Boolean);if(pts.length>1)body+=`<path d="${pts.map((p,j)=>`${j?'L':'M'}${p.px} ${p.py}`).join(' ')}" class="svg-route flow-line" style="stroke:${['#477c69','#b88e43','#9a7866'][i%3]};stroke-dashoffset:${i*7}"/>`});nodes.forEach(n=>{const p=map.get(n.id),wh=n.type==='warehouse',transit=n.type==='transit',unmet=(n.demand||0)-(n.served||0);body+=wh?`<rect x="${p.px-17}" y="${p.py-17}" width="34" height="34" rx="8" fill="#245d56"/><path d="m${p.px-9} ${p.py-4} 9-6 9 6v13h-18z" fill="none" stroke="white" stroke-width="1.3"/>`:`<circle cx="${p.px}" cy="${p.py}" r="${transit?6:17}" fill="${transit?'#c7cfc0':'#fffdf4'}" stroke="${unmet>0?'#bb7654':'#7e9b7f'}" stroke-width="${transit?0:2}"/>${!transit?`<text x="${p.px}" y="${p.py+4}" text-anchor="middle" class="svg-title">${num(n.served||0)}</text>`:''}`;if(!transit)body+=`<text x="${p.px}" y="${p.py+31}" text-anchor="middle" class="svg-small">${esc(n.name)}${n.demand?` · ${num(n.demand)} needed`:''}</text>`});body+=`<text x="35" y="321" class="svg-label">${num(d.served)} delivered · ${num(d.unmet)} unmet</text><text x="520" y="321" class="svg-label">${d.bridgeClosed?'Bridge closed · routes recalculated':'Bridge open · network available'}</text>`;return svg('Fictional road network showing warehouses, demand points, closed roads and the heuristic delivery routes.',body)}
function drawShelter(d){const points=[...(d.centres||[]).map(p=>({...p,id:'c'+p.id})),...(d.districts||[]).map(p=>({...p,id:'d'+p.id}))],map=mapped(points);let body=`<text x="35" y="30" class="svg-title">PEOPLE, PLACES AND AVAILABLE SPACE</text>`;(d.allocations||[]).forEach(a=>{const f=map.get('d'+a.from),t=map.get('c'+a.to);if(!f||!t)return;body+=`<path d="M${f.px} ${f.py}Q${(f.px+t.px)/2} ${(f.py+t.py)/2-25} ${t.px} ${t.py}" fill="none" stroke="#7f9d7b" stroke-width="${1+a.people/Math.max(1,d.population)*16}" opacity=".3"/><path d="M${f.px} ${f.py}Q${(f.px+t.px)/2} ${(f.py+t.py)/2-25} ${t.px} ${t.py}" fill="none" stroke="#6a8d70" stroke-width="1" class="flow-line" opacity=".65"/>`});(d.districts||[]).forEach(p=>{const n=map.get('d'+p.id);body+=`<circle cx="${n.px}" cy="${n.py}" r="12" fill="#dbdfcd" stroke="${p.served<p.demand?'#bd7954':'#97aa8a'}"/><text x="${n.px}" y="${n.py+4}" text-anchor="middle" class="svg-small">${num(p.demand/1000)}k</text><text x="${n.px}" y="${n.py+25}" text-anchor="middle" class="svg-small">${esc(p.name)}</text>`});(d.centres||[]).forEach(p=>{const n=map.get('c'+p.id),ratio=p.capacity?Math.min(1,p.assigned/p.capacity):0;body+=`<rect x="${n.px-35}" y="${n.py-25}" width="70" height="50" rx="15" fill="${p.active?'#fffdf4':'#ecece0'}" stroke="${p.active?'#40725e':'#bfc7b5'}" stroke-width="${p.active?2:1}" ${p.active?'':'stroke-dasharray="4 3"'}/><rect x="${n.px-23}" y="${n.py-13}" width="46" height="20" rx="6" fill="${p.active?'#dce5c7':'#d9ddcf'}"/><rect x="${n.px-23}" y="${n.py+12}" width="46" height="3" rx="1" fill="#d3dbc9"/><rect x="${n.px-23}" y="${n.py+12}" width="${46*ratio}" height="3" rx="1" fill="#5e8665"/><text x="${n.px}" y="${n.py+2}" text-anchor="middle" class="svg-small">${p.active?num(p.assigned):'Closed'}</text><text x="${n.px}" y="${n.py+39}" text-anchor="middle" class="svg-small">${esc(p.name)}</text>`});body+=`<text x="35" y="321" class="svg-label">${num(d.served)} assigned · ${num(d.unmet)} unassigned</text><text x="547" y="321" class="svg-label">${num(d.capacity)} total available capacity</text>`;return svg('Fictional districts linked to active sports-venue shelters. Occupancy bars show calculated allocation.',body)}
function pauseGuide(){guidePlaying=false;clearInterval(guideTimer)}
function toast(message){const el=$('#toast');if(!el)return;el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4500)}
function openModal(title,content){pauseGuide();$('#stage video')?.pause();if(guideOpen)renderGuide();const el=$('#modal');el.innerHTML=`<div class="modal-inner"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-button" id="modal-close" aria-label="Close dialog">${icon('close')}</button></div>${content}</div>`;$('#modal-close').onclick=()=>el.close();el.showModal()}
function showProduct(){const questions={circularbuild:'Who needs a recovery plan before a building is taken apart?',panelbuild:'Who needs to compare construction methods before committing resources?',vernacular:'Who needs to see costs and impacts beyond the purchase price?',reliefroute:'Who needs a delivery plan that can adapt when conditions change?',shelterspace:'Who needs to decide where people can be accommodated fairly?'};openModal('From this lab to a product.',`<div class="badge">THE RESEARCH → PRODUCT LENS</div><p style="margin-top:15px">${esc(questions[id])} A useful app connects the same research to different decisions.</p>${lab.roles.map(r=>`<div class="product-role"><strong>${esc(r.name)}</strong><span>${esc(r.goal)}</span></div>`).join('')}<div class="product-flow"><strong>A possible global product pathway</strong>Test with real users → replace training data with local evidence → validate the model → adapt language, currency, units and access → pilot the workflow → maintain and improve.</div><p>This prototype demonstrates a product idea. It does not establish market demand, operational reliability or commercial readiness. Your research contributes the evidence; product development makes that evidence usable.</p>`)}

/* Calculated output remains inspectable without relying on the SVG image. */
let breakdownOpen=false,resultAnnouncementTimer;
const allowsRecoveryMotion=()=>motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
function selectRecoveryView(next){
  if(!['model','scene','video'].includes(next))return;
  $('#stage video')?.pause();view=next;updateStage();
  for(const tab of document.querySelectorAll('[data-view]')){const selected=tab.dataset.view===view;tab.classList.toggle('active',selected);tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1;}
  $('#stage').setAttribute('aria-labelledby',view==='video'?'video-tab':'view-'+view);
}
function announceRecoveryResults(){clearTimeout(resultAnnouncementTimer);const summary=result.explanation;resultAnnouncementTimer=setTimeout(()=>{const status=$('#result-status');if(status)status.textContent=summary;},300);}
function resultTable(caption,columns,rows){return `<div class="calculated-table-wrap" tabindex="0" role="region" aria-label="${esc(caption)}"><table class="calculated-table"><caption>${esc(caption)}</caption><thead><tr>${columns.map(c=>`<th scope="col">${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((cell,i)=>i===0?`<th scope="row">${esc(cell)}</th>`:`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function calculatedBreakdownHtml(d){
  let tables='';
  if(id==='circularbuild'){
    tables=resultTable('Material mass balance',['Material','Removed (t)','Reuse (t)','Recycling (t)','Landfill (t)'],d.materials.map(m=>[m.name,num(m.mass),num(m.reuse),num(m.recycle),num(m.landfill)]));
    tables+=resultTable('Management cost account',['Component','Demo USD'],[['Sorting',num(d.sorting)],['Haulage',num(d.haul)],['Disposal',num(d.disposal)],['Recovery revenue (subtract)',num(d.revenue)],['Net management cost',num(d.netCost)],['All-disposal baseline',num(d.baselineCost)]]);
  }else if(id==='panelbuild'){
    tables=resultTable('Sequential programme stages',['Stage','Duration (days)'],d.stages.map(s=>[s.label,num(s.days)]));
    tables+=resultTable('Like-for-like strategy comparison',['Strategy','Days','Demo USD','Production + haul (t CO₂e)'],d.comparison.map(s=>[s.label,num(s.days),num(s.cost),num(s.carbonKg/1000)]));
  }else if(id==='vernacular'){
    tables=resultTable('Financial account at the assumed 3% real rate',['Component','Present value (demo USD)'],[['Construction',num(d.construction)],['Energy',num(d.energyPV)],['Maintenance',num(d.maintenancePV)],['End of life',num(d.endOfLifePV)],['Whole-life total',num(d.totalCost)]]);
    tables+=resultTable('Lifecycle events before discounting',['Event','Year','Event cost (demo USD)'],d.timeline.map(e=>[e.kind,num(e.year),num(e.cost)]));
  }else if(id==='reliefroute'){
    tables=resultTable('District demand and delivery',['District','Needed (kits)','Delivered (kits)','Unmet (kits)'],d.nodes.filter(n=>n.type==='demand').map(n=>[n.name,num(n.demand),num(n.served),num(n.demand-n.served)]));
    tables+=resultTable('Feasible vehicle tours, including warehouse return',['Vehicle','Load (kits)','Distance (km)','Return time (min)'],d.routes.map(r=>['Vehicle '+r.vehicle,num(r.load),num(r.km),num(r.minutes)]));
  }else{
    tables=resultTable('Arena capacity and assignment',['Arena','Status','Active capacity','Assigned people'],d.centres.map(c=>[c.name,c.active?'Open':'Closed',num(c.active?c.capacity:0),num(c.assigned)]));
    tables+=resultTable('District assignment and remaining need',['District','People needing shelter','Assigned','Unassigned'],d.districts.map(q=>[q.name,num(q.demand),num(q.served),num(q.demand-q.served)]));
  }
  return `<details class="calculated-breakdown" id="calculated-breakdown" ${breakdownOpen?'open':''}><summary>Calculated breakdown <span>Read the numbers behind the diagram ${icon('chevron')}</span></summary><div class="calculated-breakdown-body"><p>Synthetic scenario · These values use the same calculations as the results above. Displayed figures are rounded.</p>${tables}</div></details>`;
}
function updateStage(){
  const stage=$('#stage');stage.classList.toggle('model-view',view==='model');stage.classList.toggle('motion-paused',!allowsRecoveryMotion());stage.setAttribute('aria-label',view==='model'?'Live model':view==='scene'?'Concept scene':'Motion story');
  if(view==='video'){
    const src=media[id];
    // Updating a slider or role must not restart an unrelated illustrative film.
    if(stage.dataset.view==='video'&&stage.dataset.mediaSrc===src&&stage.querySelector('video'))return;
    stage.innerHTML=src?`<div class="concept-view"><video controls muted playsinline preload="metadata" poster="${A}${art[id]}.png" src="${esc(src)}" aria-label="${esc(names[id])} process illustration"></video><span class="stage-stamp">AI-generated process illustration · Explore calculated results in Live model</span></div>`:`<div class="concept-view"><img src="${A}${art[id]}.png" alt="Concept model"><span class="stage-stamp">Explore the interactive calculation in Live model.</span></div>`;
    stage.dataset.view='video';stage.dataset.mediaSrc=src||'';return;
  }
  stage.dataset.view=view;delete stage.dataset.mediaSrc;
  if(view==='scene'){stage.innerHTML=`<div class="concept-view"><img src="${A}${art[id]}.png" alt="Illustrative architectural model for ${esc(names[id])}"><span class="stage-stamp">AI-generated concept illustration · Not calculated from your inputs</span></div>`;return;}
  try{
    stage.innerHTML=`<div class="model-drawing" tabindex="0" role="region" aria-label="Interactive diagram. Scroll horizontally if needed.">${drawModel(result.details)}</div><div class="model-caption"><span>Simplified training model · ${id==='reliefroute'?'Heuristic routing, not proof of an optimum':id==='shelterspace'?'Illustrative assignment, not a safety assessment':'Synthetic scenario, calculated results'}</span><span class="model-swipe-hint" hidden>Swipe or scroll to explore the full diagram →</span></div>${calculatedBreakdownHtml(result.details)}`;
    const breakdown=$('#calculated-breakdown');breakdown.ontoggle=e=>{if(e.target.isConnected)breakdownOpen=e.target.open;};updatePanHint();
  }catch(error){console.error(error);stage.innerHTML='<div class="stage-error">The model could not be drawn. Your calculated results remain available below.</div>';}
}

function drawPanel(d){
  const stages=d.stages||[],maximum=Math.max(1,...stages.map(s=>s.days)),masonry=d.method==='masonry';
  let body=`<text x="40" y="35" class="svg-title">A CONSTRUCTION SEQUENCE</text><text x="565" y="35" class="svg-label">${num(d.units)} units · ${num(d.area)} m²</text><text x="40" y="58" class="svg-small">${esc(lab.controls.find(c=>c.key==='method').options.find(o=>o.value===d.method)?.label||'Construction strategy')}</text><ellipse cx="300" cy="202" rx="220" ry="28" fill="#d4d8c6" opacity=".4"/>`;
  for(let i=0;i<4;i++){const x=100+i*102,y=139-i*10;body+=`<path d="M${x} ${y}l35-22 78 23-35 22z" fill="#e6d7b5"/><path d="M${x} ${y}v59l78 23v-59z" fill="${masonry?'#cfaa91':'#e6e5d2'}" stroke="#bcbba4"/><path d="M${x+78} ${y+23}l35-22v59l-35 22z" fill="${masonry?'#ba927b':'#b8c5b4'}" stroke="#a8b7a4"/><path d="M${x+14} ${y+18}l17 5v30l-17-5zm32 9 16 5v18l-16-5z" fill="#6d8f83" opacity=".7"/>`;}
  if(!masonry)body+=`<g class="float-panel"><path d="m445 75 70 21v53l-70-21z" fill="#f4e8c9" stroke="#bda878"/><path d="m445 75 12-9 70 21-12 9z" fill="#dfc887"/><path d="m515 96 12-9v53l-12 9z" fill="#cdbd8e"/><path d="m470 82 12-36 19 44" fill="none" stroke="#8f907c" stroke-width="1.4"/></g><path d="M603 195V45H481v17M590 45l13-13 13 13" fill="none" stroke="#b99c55" stroke-width="5"/>`;
  body+=`<text x="638" y="110" class="svg-value">${num(d.days)}</text><text x="638" y="128" class="svg-label">days in this model</text><text x="638" y="158" class="svg-small">Baseline: ${num(d.baselineDays)} days</text>`;
  const width=720/(stages.length||1);stages.forEach((s,i)=>{const x=40+i*width,fill=s.days>0?Math.max(1,(width-16)*s.days/maximum):0;body+=`<text x="${x}" y="264" class="svg-label">${esc(s.label)}</text><rect x="${x}" y="277" width="${width-16}" height="9" rx="4" fill="#dfe3d3"/><rect data-stage-index="${i}" x="${x}" y="277" width="${fill}" height="9" rx="4" fill="${s.color||'#517f6e'}"/><text x="${x}" y="306" class="svg-title">${num(s.days)} days</text>`;});
  return svg('Conceptual housing illustration for the selected strategy, with calculated sequential stage durations. Zero-day stages have no filled duration bar.',body);
}
function drawVernacular(d){
  const layers=d.layers||[];let x=200,body=`<text x="40" y="35" class="svg-title">THE WALL, THROUGH TIME</text><text x="588" y="35" class="svg-label">${num(d.years)}-year study period</text><text x="55" y="141" class="svg-label">Outside</text><text x="581" y="141" class="svg-label">Inside</text>`;
  const totalThickness=layers.reduce((sum,l)=>sum+(l.thickness||1),0)||1;
  layers.forEach(l=>{const w=55+100*(l.thickness||1)/totalThickness;body+=`<path d="M${x} 90l35-23 ${w} 0-35 23z" fill="${l.color}" opacity=".75"/><path d="M${x} 90h${w}v112h-${w}z" fill="${l.color}" stroke="#ffffff80"/><path d="M${x+w} 90l35-23v112l-35 23z" fill="${l.color}" opacity=".55"/><text x="${x+w/2}" y="223" class="svg-small" text-anchor="middle">${esc(l.label)}</text>`;x+=w+7;});
  body+=`<path class="flow-line" d="M100 160H177M${Math.min(x+45,560)} 160h72" stroke="#bf8457" stroke-width="2" fill="none" marker-end="url(#arr)"/><text x="595" y="182" class="svg-value">${num(d.annualEnergy)}</text><text x="595" y="199" class="svg-small">kWh / year</text><text x="40" y="265" class="svg-label">Construction · maintenance (gold) · end of life</text><path d="M55 287H740" stroke="#bdc9b5" stroke-width="2"/>`;
  (d.timeline||[]).forEach((event,i)=>{const px=55+Math.min(1,event.year/d.years)*685,maintenance=String(event.kind).toLowerCase()==='maintenance';body+=`<g data-event-kind="${esc(event.kind)}"><circle cx="${px}" cy="287" r="${maintenance?5:7}" fill="${maintenance?'#c7a05a':'#56816e'}"><title>${esc(event.kind)} · year ${num(event.year)}</title></circle><text x="${px}" y="${i%2?320:307}" class="svg-small" text-anchor="middle">Year ${num(event.year)}</text></g>`;});
  return svg('Illustrative wall layers and a calculated lifecycle timeline. Gold events are maintenance. Layer widths and heat arrows are conceptual, not a dimensional drawing or thermal simulation.',body);
}

function renderGuide(){
  const body=$('#guide-body');body.hidden=!guideOpen;const toggle=$('#guide-toggle');toggle.innerHTML=icon(guideOpen?'close':'play')+(guideOpen?'Close guide':'Start guide');toggle.setAttribute('aria-expanded',String(guideOpen));
  for(const control of document.querySelectorAll('.control'))control.classList.remove('guide-target');if(!guideOpen)return;
  const steps=result.steps||[];guideStep=Math.min(guideStep,Math.max(0,steps.length-1));const step=steps[guideStep];if(!step)return;
  body.className='guide-body';body.innerHTML=`<div class="guide-step-bar"><div class="guide-step-num">Step ${guideStep+1} / ${steps.length}</div><div class="guide-progress">${steps.map((s,i)=>`<span class="${i<=guideStep?'complete':''}"></span>`).join('')}</div><div class="guide-controls"><button id="guide-back" aria-label="Previous guide step" ${guideStep===0?'disabled':''}>${icon('back')}</button><button id="guide-play" aria-label="${guidePlaying?'Pause':'Play'} guide" aria-pressed="${guidePlaying}">${icon(guidePlaying?'pause':'play')}</button><button id="guide-next" aria-label="Next guide step" ${guideStep===steps.length-1?'disabled':''}>${icon('arrow')}</button></div></div><div class="guide-copy"><h3>${esc(step.title)}</h3><p>${esc(step.text)}</p></div>`;
  const control=$(`[data-control="${esc(step.controlKey)}"]`);if(control)control.classList.add('guide-target');
  $('#guide-back').onclick=()=>{pauseGuide();guideStep--;renderGuide();};$('#guide-next').onclick=()=>{pauseGuide();guideStep++;renderGuide();};
  $('#guide-play').onclick=()=>{if(guidePlaying){pauseGuide();renderGuide();return;}if(!allowsRecoveryMotion()){toast('Motion is reduced. Use Previous and Next to follow the same worked guide at your own pace.');return;}guidePlaying=true;if(guideStep===steps.length-1)guideStep=0;renderGuide();guideTimer=setInterval(()=>{if(guideStep<steps.length-1){guideStep++;renderGuide();}else{pauseGuide();renderGuide();}},8000);};
}
function scenarioInputValue(control,inputs){const value=inputs[control.key];if(control.type==='select')return control.options.find(option=>option.value===value)?.label||String(value);return num(value)+(control.unit?' '+control.unit:'');}
function showCompare(){
  if(!saved)return;
  const changed=lab.controls.filter(control=>saved.inputs[control.key]!==state[control.key]);
  const inputs=changed.length?`<table class="compare-table"><caption>Inputs that changed</caption><thead><tr><th scope="col">Input</th><th scope="col">Scenario A</th><th scope="col">Scenario B</th></tr></thead><tbody>${changed.map(control=>`<tr><th scope="row">${esc(control.label)}</th><td>${esc(scenarioInputValue(control,saved.inputs))}</td><td>${esc(scenarioInputValue(control,state))}</td></tr>`).join('')}</tbody></table>`:'<p class="compare-no-change">No inputs have changed since capturing A. Both scenarios use the same inputs.</p>';
  openModal('Compare your scenarios',`<p>Scenario A was captured for this visit. Scenario B uses the current workspace. ${changed.length?`${changed.length} ${changed.length===1?'input has':'inputs have'} changed.`:'Capture a baseline, then change an input to investigate its effect.'}</p>${inputs}<table class="compare-table"><caption>Calculated results</caption><thead><tr><th scope="col">Result</th><th scope="col">Scenario A</th><th scope="col">Scenario B · current</th></tr></thead><tbody>${result.metrics.map((metric,i)=>`<tr><th scope="row">${esc(metric.label)}</th><td>${num(saved.result.metrics[i]?.value)} <small>${esc(metric.unit)}</small></td><td>${num(metric.value)} <small>${esc(metric.unit)}</small></td></tr>`).join('')}</tbody></table><p class="compare-scope-note">Both scenarios use the same simplified training model and illustrative coefficients. A lower or higher number is not automatically better across every result. Scenario A is held in this page’s memory; export it if you want a copy after leaving.</p>`);
}

/* A first-use example makes one real change, with the visitor's workspace kept. */
const workedExamples={
  circularbuild:{key:'sorting',from:20,to:80,metric:1,question:'What happens when more material is sorted?',lesson:'Sorting changes how much material can be recovered. Compare the cost and carbon proxies separately; recovery alone does not establish the best plan.'},
  panelbuild:{key:'method',from:'masonry',to:'panel',metric:0,question:'How does the construction strategy change the schedule?',lesson:'The programme and site crews stay the same. A shorter schedule can come with a different purchase, plant and transport cost.'},
  vernacular:{key:'climate',from:'mild',to:'cold',metric:1,question:'What changes when the same wall meets a colder climate?',lesson:'The building, wall choice and study period stay the same. This is a sensitivity test using an illustrative energy model, not a real thermal simulation.'},
  reliefroute:{key:'bridge',from:'open',to:'closed',metric:2,question:'What does losing one bridge change?',lesson:'The same fleet and demand use different open-road routes. Distance changes here while unmet demand stays visible; a route change does not necessarily change coverage.'},
  shelterspace:{key:'centres',from:3,to:4,metric:1,question:'What happens when one more arena opens?',lesson:'Population and space per person stay the same. An additional site can close a capacity gap; travel and protection needs still require separate attention.'},
};
let workedDemo=null;
function workedExampleFor(labId){const recipe=workedExamples[labId],owner=labs.find(item=>item.id===labId);if(!recipe||!owner)return null;const baseline={...owner.defaults,[recipe.key]:recipe.from};return {...recipe,baseline,changed:{...baseline,[recipe.key]:recipe.to}};}
function syncRecoveryControls(){for(const control of lab.controls){const input=$('#c-'+control.key);if(input)input.value=state[control.key];const output=$('#o-'+control.key);if(output)output.textContent=num(state[control.key])+' '+(control.unit||'');}const roleInput=$('#role');if(roleInput)roleInput.value=role;const goal=$('#role-goal');if(goal)goal.textContent=lab.roles[role].goal;}
function syncCapturedScenario(){const compare=$('#compare');if(compare)compare.disabled=!saved;const capture=$('#save');if(capture)capture.innerHTML=icon(saved?'check':'save')+(saved?' Scenario A captured':' Capture scenario A');}
function clearWorkedFocus(){for(const element of document.querySelectorAll('.worked-target'))element.classList.remove('worked-target');}
function focusWorkedExample(){
  clearWorkedFocus();if(!workedDemo||workedDemo.customized)return;
  const target=workedDemo.phase===0?$('.scenario-panel'):workedDemo.phase===1?$('[data-control="'+workedDemo.recipe.key+'"]'):workedDemo.phase===2?[...document.querySelectorAll('.metric')][workedDemo.recipe.metric]||$('#metrics'):$('.workspace-actions');
  if(!target)return;target.classList.add('worked-target');target.scrollIntoView?.({behavior:allowsRecoveryMotion()?'smooth':'auto',block:'center'});
  if(allowsRecoveryMotion()&&target.animate)target.animate([{boxShadow:'0 0 0 0 rgba(173,132,80,0)'},{boxShadow:'0 0 0 6px rgba(173,132,80,.2)'},{boxShadow:'0 0 0 2px rgba(173,132,80,.12)'}],{duration:900,easing:'ease-out'});
}
function startWorkedExample(){
  pauseGuide();const backup=workedDemo?.backup||{state:{...state},saved:saved?structuredClone(saved):null,role,view,guideOpen,guideStep};
  const recipe=workedExampleFor(id),baselineResult=simulate(id,recipe.baseline);
  workedDemo={recipe,backup,phase:0,customized:false,baselineResult};state={...recipe.baseline};saved={inputs:{...state},result:structuredClone(baselineResult)};guideOpen=false;guideStep=0;
  syncRecoveryControls();syncCapturedScenario();selectRecoveryView('model');update();focusWorkedExample();toast('Sample A is ready. Your previous workspace is kept until you choose to restore or keep this sample.');
}
function markWorkedCustomized(){if(!workedDemo)return;workedDemo.customized=true;clearWorkedFocus();renderWorkedExample();}
function advanceWorkedExample(){
  if(!workedDemo||workedDemo.customized)return;pauseGuide();workedDemo.detailsOpen=false;
  if(workedDemo.phase===0){workedDemo.phase=1;renderWorkedExample();focusWorkedExample();return;}
  if(workedDemo.phase===1){workedDemo.phase=2;state={...workedDemo.recipe.changed};syncRecoveryControls();selectRecoveryView('model');update();focusWorkedExample();return;}
  if(workedDemo.phase===2){workedDemo.phase=3;renderWorkedExample();clearWorkedFocus();showCompare();return;}
  renderWorkedExample();guideOpen=true;guideStep=0;selectRecoveryView('model');renderGuide();$('#guide-body').scrollIntoView?.({behavior:allowsRecoveryMotion()?'smooth':'auto',block:'center'});
}
function finishWorkedExample(restore){
  if(!workedDemo)return;pauseGuide();const backup=workedDemo.backup;workedDemo=null;clearWorkedFocus();
  if(restore){state={...backup.state};saved=backup.saved?structuredClone(backup.saved):null;role=backup.role;guideOpen=backup.guideOpen;guideStep=backup.guideStep;syncRecoveryControls();syncCapturedScenario();selectRecoveryView(backup.view);update();toast('Your previous inputs, comparison and view are restored. Guide playback stays paused.');}
  else{renderWorkedExample();toast('You are exploring the sample. Scenario A remains available for comparison during this visit.');}
}
function renderWorkedExample(){
  const panel=$('#worked-example-panel');if(!panel)return;
  panel.classList.toggle('active-example',!!workedDemo);
  if(!workedDemo){panel.innerHTML=`<div class="worked-example-intro"><span class="worked-example-kicker">New to this lab?</span><h2>See one change become a result.</h2><p>A short, four-step example uses sample inputs. Your current workspace can be restored afterwards.</p></div><button class="button primary" id="start-worked-example">${icon('play')} Try a worked example</button>`;$('#start-worked-example').onclick=startWorkedExample;return;}
  const {recipe,phase,customized}=workedDemo,control=lab.controls.find(c=>c.key===recipe.key),before=workedDemo.baselineResult.metrics[recipe.metric],after=result.metrics[recipe.metric];
  const from=scenarioInputValue(control,recipe.baseline),to=scenarioInputValue(control,recipe.changed);
  const titles=['Read the inputs','Plan one change','Read the result','Explore the method'];
  const text=customized?'You changed the inputs, so the sample is paused. Compare the current version with A, restart the example, or restore your previous workspace.':phase===0?'Scenario A is captured from the sample inputs shown below. Read the four controls, then inspect the one planned change.':phase===1?'Only '+control.label.toLowerCase()+' will change. The other sample inputs stay fixed. Choose Apply change to calculate B.':phase===2?recipe.lesson:'Both scenarios remain available. Open the worked calculation for the current values, or continue exploring on your own.';
  const shortLabel={sorting:'Sorting',method:'Strategy',climate:'Climate',bridge:'Bridge',centres:'Active arenas'}[recipe.key]||control.label;
  panel.innerHTML=`<div class="worked-compact-head"><div class="worked-compact-title"><span class="worked-step-count" aria-label="Step ${phase+1} of 4">${phase+1} / 4</span><h2>${esc(customized?'Sample paused':titles[phase])}</h2></div><button class="button primary" id="next-worked-example" aria-label="${esc(customized?'Compare your current scenario with A':['See the planned single input change','Apply the planned change and calculate B','Compare scenarios A and B','Open the worked calculation guide'][phase])}">${esc(customized?'Compare A / B':['Next','Apply change','Compare A / B','Open guide'][phase])} ${icon('arrow')}</button></div><div class="worked-example-change"><strong title="${esc(control.label)}">${esc(shortLabel)}</strong><span>${esc(from)}</span>${icon('arrow')}<span>${esc(to)}</span>${customized?'<small>Example paused</small>':''}</div><div class="worked-compact-footer"><button class="text-button" id="restore-worked-example">Restore my workspace</button><button class="text-button" id="worked-details-toggle" aria-expanded="${!!workedDemo.detailsOpen}" aria-controls="worked-details-body">Example details ${icon('chevron')}</button></div><div class="worked-example-expanded" id="worked-details-body" ${workedDemo.detailsOpen?'':'hidden'}><h3>${esc(recipe.question)}</h3><p>${esc(text)}</p>${phase>=2&&!customized?`<div class="worked-example-result" role="status"><strong>${esc(before.label)}</strong><span>A: ${num(before.value)} ${esc(before.unit)}</span>${icon('arrow')}<span>B: ${num(after.value)} ${esc(after.unit)}</span></div>`:''}<div class="worked-example-secondary">${phase>=2||customized?'<button class="text-button" id="restart-worked-example">Restart example</button>':''}<button class="text-button" id="keep-worked-example">Keep exploring this sample</button></div></div>`;
  $('#next-worked-example').onclick=customized?showCompare:advanceWorkedExample;$('#restore-worked-example').onclick=()=>finishWorkedExample(true);$('#keep-worked-example').onclick=()=>finishWorkedExample(false);if($('#restart-worked-example'))$('#restart-worked-example').onclick=startWorkedExample;
  $('#worked-details-toggle').onclick=()=>{workedDemo.detailsOpen=!workedDemo.detailsOpen;renderWorkedExample();$('#worked-details-toggle').focus({preventScroll:true});};
}

if(lab)renderLab();else if(location.pathname.startsWith(FIELD))renderCollection();else renderHub();



